import AVFoundation
import Foundation
import QuranCore
import XCTest
@testable import Sakina

/// Frozen representative JSON for the actual v1 writers at e1bb262 (build53)
/// and af37c3c (before display choices). The values are synthetic. Crucially,
/// these old inputs are literals, not regenerated by the current encoder with
/// fields removed. They verify schema upgrades, not a signed device installation.
@MainActor
final class UpgradeCompatibilityTests: XCTestCase {
    func testBuild53StateAndAudioPreferencesSurviveNewSaveAndRelaunch() throws {
        let storage = try isolatedDefaults()
        storage.set(Self.build53State, forKey: "sakina.reading-state.v1")
        storage.set("husary", forKey: "sakina.audio.reciter.v1")
        storage.set(false, forKey: "sakina.audio.autoplay.v1")
        let store = makeStore(storage)
        try assertBuild53Progress(store)
        XCTAssertTrue(store.practiceQueue.isEmpty, "The old writer has no queue field")

        var assetRequests = 0
        let player = RecitationPlayer(player: AVPlayer(), audioURL: { _, _ in
            assetRequests += 1
            return URL(fileURLWithPath: "/unused-upgrade-fixture.wav")
        }, defaults: storage, integratesWithSystemAudio: false)
        defer { player.stop() }
        XCTAssertEqual(player.selectedReciter, .husary)
        XCTAssertFalse(player.autoplay)
        XCTAssertEqual(assetRequests, 0, "Restoring preferences must not begin playback or load media")

        let added = try reference(1, 4)
        store.toggleBookmark(added) // Exercise the new writer without earning credit.
        let rewritten = try XCTUnwrap(storage.data(forKey: "sakina.reading-state.v1"))
        XCTAssertNotEqual(rewritten, Self.build53State)
        let relaunched = makeStore(storage)
        try assertBuild53Progress(relaunched, extraBookmark: added)
        XCTAssertTrue(relaunched.practiceQueue.isEmpty)
        XCTAssertEqual(storage.string(forKey: "sakina.audio.reciter.v1"), "husary")
        XCTAssertEqual(storage.object(forKey: "sakina.audio.autoplay.v1") as? Bool, false)
    }

    func testPreDisplayChoiceStateKeepsHistoryWhileNewChoicesUseSafeDefaults() throws {
        let storage = try isolatedDefaults()
        storage.set(Self.preDisplayChoicesState, forKey: "sakina.reading-state.v1")
        let store = makeStore(storage)
        XCTAssertEqual(store.lastRead, try reference(2, 255))
        XCTAssertEqual(store.selectedSurahID, 2)
        XCTAssertEqual(store.arabicTextSize, .standard)
        XCTAssertEqual(store.appearance, .system)
        XCTAssertEqual(store.todayReadCount, 1)
        XCTAssertEqual(store.streakSummary.current, 2)
        XCTAssertEqual(store.streakSummary.best, 2)
        XCTAssertFalse(store.tajweedEnabled)
        store.setAppearance(.dark)
        store.setArabicTextSize(.large)
        let restored = makeStore(storage)
        XCTAssertEqual(restored.todayReadCount, 1)
        XCTAssertEqual(restored.streakSummary.current, 2)
        XCTAssertEqual(restored.lastRead, try reference(2, 255))
        XCTAssertEqual(restored.appearance, .dark)
        XCTAssertEqual(restored.arabicTextSize, .large)
        XCTAssertTrue(restored.practiceQueue.isEmpty)
    }

    func testBuild53BackupKeepsNewQueueSettingsAndPositionWithoutAddingTodayCredit() throws {
        let storage = try isolatedDefaults()
        let target = makeStore(storage)
        let current = try reference(2, 255)
        let queued = try reference(112, 2)
        target.setLastRead(current)
        target.setDailyGoal(7)
        target.setTajweedEnabled(false)
        target.setAppearance(.dark)
        target.setArabicTextSize(.extraLarge)
        XCTAssertTrue(target.togglePracticeQueue(queued))

        try target.mergeReadingBackup(Self.build53Backup)
        try target.mergeReadingBackup(Self.build53Backup)
        XCTAssertEqual(target.lastRead, current)
        XCTAssertEqual(target.practiceQueue, [queued], "Missing old field must not erase a newer queue")
        XCTAssertEqual(target.dailyGoal, 7)
        XCTAssertFalse(target.tajweedEnabled)
        XCTAssertEqual(target.appearance, .dark)
        XCTAssertEqual(target.arabicTextSize, .extraLarge)
        XCTAssertEqual(target.todayReadCount, 0)
        XCTAssertFalse(target.dailyGoalMet)
        XCTAssertEqual(target.streakSummary.current, 1, "Only the imported historical completion is counted")
        XCTAssertEqual(target.bookmarks, [try reference(1, 1)])
        let restored = makeStore(storage)
        XCTAssertEqual(restored.practiceQueue, [queued])
        XCTAssertEqual(restored.lastRead, current)
        XCTAssertEqual(restored.todayReadCount, 0)
        XCTAssertEqual(restored.appearance, .dark)
        XCTAssertEqual(restored.arabicTextSize, .extraLarge)
    }

    func testLegacyAudioLayoutSurvivesStateUpgradeAndReopensWithoutNetwork() throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("sakina.upgrade-audio.\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        // Exact layout used by build53, intentionally not derived from the new
        // inventory's path helpers or names. No sidecar/index migration required.
        let folder = root.appendingPathComponent("husary/112", isDirectory: true)
        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let file = folder.appendingPathComponent("112002.mp3")
        let bytes = try XCTUnwrap(GeneratedMP3Fixture.data)
        try bytes.write(to: file)
        let writtenAt = Date(timeIntervalSince1970: 1_000)
        try FileManager.default.setAttributes([.modificationDate: writtenAt], ofItemAtPath: file.path)
        let storage = try isolatedDefaults()
        storage.set(Self.build53State, forKey: "sakina.reading-state.v1")
        let reference = try reference(112, 2)
        let library = AudioLibrary(directory: root, download: { _, _ in
            XCTFail("Reading an upgraded local library must not request the network")
            throw URLError(.notConnectedToInternet)
        })
        XCTAssertEqual(library.localURL(for: reference, reciter: .husary), file)
        XCTAssertEqual(library.downloadedVerseCount(surahID: 112, reciter: .husary), 1)
        makeStore(storage).setAppearance(.light) // Commit a current-format state.
        let reopened = AudioLibrary(directory: root, download: { _, _ in
            XCTFail("Reopening a legacy file must remain local")
            throw URLError(.notConnectedToInternet)
        })
        XCTAssertEqual(reopened.localURL(for: reference, reciter: .husary), file)
        XCTAssertEqual(try Data(contentsOf: file), bytes)
        XCTAssertEqual(try FileManager.default.attributesOfItem(atPath: file.path)[.modificationDate] as? Date, writtenAt)
        XCTAssertEqual(makeStore(storage).todayReadCount, 1)
    }

    private func makeStore(_ defaults: UserDefaults) -> AppStore {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(secondsFromGMT: 0)!
        let date = calendar.date(from: DateComponents(year: 2026, month: 10, day: 25, hour: 12))!
        return AppStore(defaults: defaults, now: { date }, calendar: { calendar })
    }

    private func isolatedDefaults() throws -> UserDefaults {
        let name = "sakina.upgrade-tests.\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: name))
        addTeardownBlock { defaults.removePersistentDomain(forName: name) }
        return defaults
    }

    private func reference(_ surah: Int, _ ayah: Int) throws -> AyahReference {
        try XCTUnwrap(AyahReference(surahID: surah, ayahNumber: ayah))
    }

    private func assertBuild53Progress(_ store: AppStore, extraBookmark: AyahReference? = nil,
                                      file: StaticString = #filePath, line: UInt = #line) throws {
        var expected: Set<AyahReference> = [try reference(2, 255), try reference(112, 1)]
        if let extraBookmark { expected.insert(extraBookmark) }
        XCTAssertEqual(store.selectedSurahID, 2, file: file, line: line)
        XCTAssertEqual(store.lastRead, try reference(2, 255), file: file, line: line)
        XCTAssertEqual(store.bookmarks, expected, file: file, line: line)
        XCTAssertEqual(store.arabicTextSize, .extraLarge, file: file, line: line)
        XCTAssertEqual(store.appearance, .dark, file: file, line: line)
        XCTAssertFalse(store.tajweedEnabled, file: file, line: line)
        XCTAssertEqual(store.dailyGoal, 1, file: file, line: line)
        XCTAssertEqual(store.todayReadCount, 1, file: file, line: line)
        XCTAssertTrue(store.dailyGoalMet, file: file, line: line)
        XCTAssertEqual(store.streakSummary.current, 2, file: file, line: line)
        XCTAssertEqual(store.streakSummary.best, 2, file: file, line: line)
    }

    private static let build53State = Data(#"""
    {"version":1,"selectedSurahID":2,"lastRead":{"surahID":2,"ayahNumber":255},"bookmarks":[{"surahID":2,"ayahNumber":255},{"surahID":112,"ayahNumber":1}],"tajweedEnabled":false,"arabicTextSize":"extraLarge","appearance":"dark","dailyGoal":1,"streak":{"completionDays":[{"year":2026,"month":10,"day":24},{"year":2026,"month":10,"day":25}]},"readAyahsByDay":{"2026-10-25":[{"surahID":2,"ayahNumber":255}]}}
    """#.utf8)

    private static let preDisplayChoicesState = Data(#"""
    {"version":1,"selectedSurahID":2,"lastRead":{"surahID":2,"ayahNumber":255},"bookmarks":[{"surahID":2,"ayahNumber":255},{"surahID":112,"ayahNumber":1}],"tajweedEnabled":false,"dailyGoal":1,"streak":{"completionDays":[{"year":2026,"month":10,"day":24},{"year":2026,"month":10,"day":25}]},"readAyahsByDay":{"2026-10-25":[{"surahID":2,"ayahNumber":255}]}}
    """#.utf8)

    private static let build53Backup = Data(#"""
    {"format":"sakina-reading-backup","version":1,"exportedAt":"2026-10-24T12:00:00Z","bookmarks":[{"surahID":1,"ayahNumber":1}],"lastRead":{"surahID":1,"ayahNumber":1},"completedDays":[{"year":2026,"month":10,"day":24}],"readAyahsByDay":{"2026-10-24":[{"surahID":1,"ayahNumber":1}]}}
    """#.utf8)
}
